def band_minutes(start: int, end: int) -> dict:
    if start > end:
        raise ValueError("start must be <= end")
    length = end - start
    if length < 5:
        return {"day": 0, "night": 0, "weekend": 0}

    WEEKEND = [(7200, 10079)]
    NIGHT = []
    DAY = []
    for d in range(5):
        base = d * 1440
        NIGHT.append((base, base + 359))
        NIGHT.append((base + 1320, base + 1439))
        DAY.append((base + 360, base + 1319))

    def count_in_band(intervals, n):
        """Count integers m in [0, n) whose m % 10080 falls in any interval."""
        q, r = divmod(n, 10080)
        total = q * sum(hi - lo + 1 for lo, hi in intervals)
        for lo, hi in intervals:
            if r > lo:
                total += min(hi + 1, r) - lo
        return total

    def round_up_15(c):
        return 0 if c == 0 else ((c + 14) // 15) * 15

    raw_day = count_in_band(DAY, end) - count_in_band(DAY, start)
    raw_night = count_in_band(NIGHT, end) - count_in_band(NIGHT, start)
    raw_weekend = count_in_band(WEEKEND, end) - count_in_band(WEEKEND, start)

    return {
        "day": round_up_15(raw_day),
        "night": round_up_15(raw_night),
        "weekend": round_up_15(raw_weekend),
    }
