from collections import deque


def kin_distance(parents: dict, a: str, b: str) -> tuple:
    """Measure how two people in a family record are related."""

    def _ancestors(person: str) -> dict:
        """BFS from `person` up the family tree; returns {ancestor: min_distance}."""
        dist = {person: 0}
        queue = deque([person])
        while queue:
            cur = queue.popleft()
            d = dist[cur]
            for p in parents.get(cur, []):
                if p not in dist:
                    dist[p] = d + 1
                    queue.append(p)
        return dist

    dist_a = _ancestors(a)
    dist_b = _ancestors(b)

    best = None
    for c, da in dist_a.items():
        if c in dist_b:
            db = dist_b[c]
            if best is None or (da + db, da) < (best[0] + best[1], best[0]):
                best = (da, db)

    return best
