import re

def expand_slots(spec: str) -> list[str]:
    if not spec.strip():
        return []

    tokens = spec.split(',')
    result: list[str] = []
    in_result: set[str] = set()

    slot_pattern = re.compile(r'([A-Z])([1-9][0-9]?)')

    for raw_token in tokens:
        token = raw_token.strip()
        if token == '':
            raise ValueError(f"Empty token in slot spec: {spec!r}")

        is_removal = token.startswith('!')
        if is_removal:
            token = token[1:]

        # Determine if this is a range or single slot
        if '-' in token:
            parts = token.split('-')
            if len(parts) != 2:
                raise ValueError(f"Invalid token: {raw_token}")
            slot1, slot2 = parts
            m1 = slot_pattern.fullmatch(slot1)
            m2 = slot_pattern.fullmatch(slot2)
            if not m1 or not m2:
                raise ValueError(f"Invalid slot in token: {raw_token}")
            if m1.group(1) != m2.group(1):
                raise ValueError(f"Range ends must share the same letter: {raw_token}")
            letter = m1.group(1)
            n1, n2 = int(m1.group(2)), int(m2.group(2))
            if n1 <= n2:
                slots = [f"{letter}{i}" for i in range(n1, n2 + 1)]
            else:
                slots = [f"{letter}{i}" for i in range(n1, n2 - 1, -1)]
        else:
            m = slot_pattern.fullmatch(token)
            if not m:
                raise ValueError(f"Invalid token: {raw_token}")
            slots = [token]

        if is_removal:
            for slot in slots:
                if slot in result:
                    result.remove(slot)
                    in_result.discard(slot)
        else:
            for slot in slots:
                if slot not in in_result:
                    result.append(slot)
                    in_result.add(slot)

    return result
