def top_spenders(events: list[dict], k: int) -> list[tuple[str, int]]:
    if k == 0 or not events:
        return []

    # Sort by (ts, original_index) — stable processing order
    indexed_events = [(e, i) for i, e in enumerate(events)]
    indexed_events.sort(key=lambda x: (x[0]["ts"], x[1]))

    # order_id -> {"customer": str, "amount": int, "cancelled": bool}
    orders: dict[str, dict] = {}
    # customer -> timestamp of earliest accepted buy
    earliest_buy: dict[str, int] = {}

    for event, _ in indexed_events:
        etype = event["type"]

        if etype == "buy":
            order_id = event["order"]
            customer = event["customer"]
            cents = event["cents"]
            if order_id not in orders:
                orders[order_id] = {"customer": customer, "amount": cents, "cancelled": False}
                if customer not in earliest_buy:
                    earliest_buy[customer] = event["ts"]
            # else: order id already seen in a buy -> ignore entirely

        elif etype == "refund":
            order_id = event["order"]
            cents = event["cents"]
            if order_id in orders and not orders[order_id]["cancelled"]:
                orders[order_id]["amount"] = max(0, orders[order_id]["amount"] - cents)

        elif etype == "cancel":
            order_id = event["order"]
            if order_id in orders:
                orders[order_id]["amount"] = 0
                orders[order_id]["cancelled"] = True

    # Sum current order amounts per customer
    customer_totals: dict[str, int] = {}
    for order in orders.values():
        c = order["customer"]
        customer_totals[c] = customer_totals.get(c, 0) + order["amount"]

    # Build ranking list (exclude zero totals)
    ranked = []
    for customer, total in customer_totals.items():
        if total > 0:
            ranked.append((customer, total, earliest_buy[customer]))

    # Sort: total desc, earliest-buy-ts asc, name asc
    ranked.sort(key=lambda r: (-r[1], r[2], r[0]))

    return [(r[0], r[1]) for r in ranked[:k]]
