import re


def parse_stanza(text: str) -> dict:
    result: dict = {}
    current_section = None

    for line in text.split("\n"):
        # Step 1: Remove comment (scan left to right, tracking quoted mode)
        in_quotes = False
        cut = len(line)
        for i, ch in enumerate(line):
            if ch == '"':
                in_quotes = not in_quotes
            elif ch == "#" and not in_quotes:
                cut = i
                break
        line = line[:cut]

        # Step 2: Strip whitespace; skip blank lines
        line = line.strip()
        if not line:
            continue

        # Step 3: Section header
        if line.startswith("[") and line.endswith("]"):
            name = line[1:-1].strip()
            if not name:
                raise ValueError("empty section name")
            if name not in result:
                result[name] = {}
            current_section = name
            continue

        # Step 4: Entry
        if "=" not in line:
            raise ValueError("entry must contain '='")
        key, raw_value = line.split("=", 1)
        key = key.strip()
        raw_value = raw_value.strip()
        if not key:
            raise ValueError("empty key")

        # Step 5: Default section
        if current_section is None:
            current_section = ""
            # The "" section is created here (it has at least one entry)
            if current_section not in result:
                result[current_section] = {}

        # Convert value and assign (Step 6: later replaces earlier)
        result[current_section][key] = _convert(raw_value)

    return result


def _convert(raw: str):
    # a. Quoted string
    if len(raw) >= 2 and raw[0] == '"' and raw[-1] == '"':
        return raw[1:-1]

    # b. Pipe-delimited list
    if "|" in raw:
        return [_convert_piece(p) for p in raw.split("|")]

    # c. Scalar
    return _convert_piece(raw)


def _convert_piece(piece: str):
    piece = piece.strip()
    if piece == "":
        return ""
    if re.fullmatch(r"-?\d+", piece):
        return int(piece)
    if piece == "yes":
        return True
    if piece == "no":
        return False
    return piece
