def run_tally(program: str, max_steps: int) -> tuple[str, list[int]]:
    tokens = program.split()
    n = len(tokens)
    stack = []
    output = []
    pc = 0
    executed = 0

    def is_int_literal(s: str) -> bool:
        if s[0] == '-':
            return len(s) > 1 and s[1:].isdigit()
        return s.isdigit()

    while True:
        if pc == n:
            return ("done", output)
        if executed == max_steps:
            return ("limit", output)

        token = tokens[pc]
        executed += 1

        # Integer literal
        if is_int_literal(token):
            stack.append(int(token))
            pc += 1
        # dup
        elif token == "dup":
            if len(stack) < 1:
                return ("fault", output)
            stack.append(stack[-1])
            pc += 1
        # drop
        elif token == "drop":
            if len(stack) < 1:
                return ("fault", output)
            stack.pop()
            pc += 1
        # swap
        elif token == "swap":
            if len(stack) < 2:
                return ("fault", output)
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1
        # add / sub / mul
        elif token in ("add", "sub", "mul"):
            if len(stack) < 2:
                return ("fault", output)
            b = stack.pop()
            a = stack.pop()
            if token == "add":
                stack.append(a + b)
            elif token == "sub":
                stack.append(a - b)
            else:
                stack.append(a * b)
            pc += 1
        # out
        elif token == "out":
            if len(stack) < 1:
                return ("fault", output)
            output.append(stack.pop())
            pc += 1
        # jmp:K
        elif token.startswith("jmp:"):
            k_str = token[4:]
            if not (k_str.isdigit() or (len(k_str) > 1 and k_str[0] == '-' and k_str[1:].isdigit())):
                return ("fault", output)
            k = int(k_str)
            target = pc + k
            if target < 0 or target > n:
                return ("fault", output)
            pc = target
        # jz:K
        elif token.startswith("jz:"):
            k_str = token[3:]
            if not (k_str.isdigit() or (len(k_str) > 1 and k_str[0] == '-' and k_str[1:].isdigit())):
                return ("fault", output)
            k = int(k_str)
            if len(stack) < 1:
                return ("fault", output)
            val = stack.pop()
            if val == 0:
                target = pc + k
                if target < 0 or target > n:
                    return ("fault", output)
                pc = target
            else:
                pc += 1
        # Malformed token
        else:
            return ("fault", output)
