def plan_rounds(deps: dict, capacity: int) -> list[list[str]]:
    if capacity < 1:
        raise ValueError("capacity must be at least 1")

    for task, prereqs in deps.items():
        for preq in prereqs:
            if preq not in deps:
                raise ValueError(f"prerequisite '{preq}' of task '{task}' is not a key in deps")

    if not deps:
        return []

    # Precompute the fixed number of direct dependents for each task.
    dependents = {task: 0 for task in deps}
    for task, prereqs in deps.items():
        for preq in prereqs:
            dependents[preq] += 1

    done: set = set()
    remaining: set = set(deps)
    rounds: list[list[str]] = []

    while remaining:
        # A task is ready when every prerequisite is in `done`.
        ready = [t for t in remaining if all(p in done for p in deps[t])]

        if not ready:
            raise ValueError("dependency cycle detected")

        # Highest number of direct dependents first; ties broken by name ascending.
        ready.sort(key=lambda t: (-dependents[t], t))

        current_round = ready[:capacity]
        rounds.append(current_round)

        for task in current_round:
            done.add(task)
            remaining.discard(task)

    return rounds
