def kth_badge(length: int, k: int) -> str:
    if length < 1:
        raise ValueError("length must be at least 1")
    if k < 1:
        raise ValueError("k must be at least 1")

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count(remaining, prev):
        """Number of valid completions with `remaining` positions left to fill,
        given that the previously placed character is `prev`."""
        if remaining == 0:
            return 1
        total = 0
        for c in "ABCD":
            if c == prev:
                continue
            if prev == "A" and c == "D":
                continue
            total += count(remaining - 1, c)
        return total

    # Total number of valid badges of the given length
    total = sum(count(length - 1, c) for c in "ABCD")
    if k > total:
        raise ValueError(f"k={k} exceeds the number of valid badges ({total})")

    result = []
    prev = None
    for pos in range(length):
        for c in "ABCD":
            if prev is not None:
                if c == prev:
                    continue
                if prev == "A" and c == "D":
                    continue
            cnt = count(length - pos - 1, c)
            if k > cnt:
                k -= cnt
            else:
                result.append(c)
                prev = c
                break
    return "".join(result)
