def number_outline(entries: list[tuple[int, str]]) -> list[str]:
    if not entries:
        return []

    def _to_letters(n: int) -> str:
        result = []
        while n > 0:
            n -= 1
            result.append(chr(ord('a') + n % 26))
            n //= 26
        return ''.join(reversed(result))

    def _to_roman(n: int) -> str:
        val_sym = [
            (1000, 'm'), (900, 'cm'), (500, 'd'), (400, 'cd'),
            (100, 'c'), (90, 'xc'), (50, 'l'), (40, 'xl'),
            (10, 'x'), (9, 'ix'), (5, 'v'), (4, 'iv'), (1, 'i'),
        ]
        result = []
        for val, sym in val_sym:
            while n >= val:
                result.append(sym)
                n -= val
        return ''.join(result)

    counters: dict[int, int] = {}
    prev_eff_depth = 0
    output: list[str] = []

    for requested_depth, title in entries:
        if requested_depth < 1:
            raise ValueError(f"Requested depth {requested_depth} is below 1")

        if prev_eff_depth == 0:
            eff_depth = 1
        else:
            eff_depth = min(requested_depth, prev_eff_depth + 1)

        counters[eff_depth] = counters.get(eff_depth, 0) + 1
        for level in sorted(counters.keys()):
            if level > eff_depth:
                counters[level] = 0

        parts = []
        for level in range(1, eff_depth + 1):
            count = counters[level]
            style = level % 3
            if style == 1:
                parts.append(str(count))
            elif style == 2:
                parts.append(_to_letters(count))
            else:
                parts.append(_to_roman(count))

        label = ".".join(parts)
        indent = " " * (2 * (eff_depth - 1))
        output.append(f"{indent}{label}) {title}")

        prev_eff_depth = eff_depth

    return output
