class BulkCache:
    def __init__(self, capacity: int):
        self._capacity = capacity
        self._order = []       # keys in insertion order (oldest first)
        self._store = {}       # key -> (value, size)
        self._total = 0        # sum of sizes of all stored entries

    def put(self, key, value, size: int) -> bool:
        if size > self._capacity:
            return False

        just_put = key

        if key in self._store:
            # Existing key: update value and size, keep its position
            self._total -= self._store[key][1]
            self._store[key] = (value, size)
            self._total += size
        else:
            # New key: append to the end (newest)
            self._order.append(key)
            self._store[key] = (value, size)
            self._total += size

        # Evict while over capacity; the key just put is never a candidate
        while self._total > self._capacity:
            max_size = -1
            evict_idx = -1
            for i, k in enumerate(self._order):
                if k == just_put:
                    continue
                s = self._store[k][1]
                if s > max_size:
                    max_size = s
                    evict_idx = i

            evict_key = self._order.pop(evict_idx)
            _, evict_size = self._store.pop(evict_key)
            self._total -= evict_size

        return True

    def get(self, key, default=None):
        if key in self._store:
            return self._store[key][0]
        return default

    def keys(self) -> list:
        return list(self._order)

    def used(self) -> int:
        return self._total
