class DraftPad:
    def __init__(self):
        self._text = ""
        self._undo_stack = []
        self._redo_stack = []
        self._typing_buf = None

    def _commit_typing(self):
        if self._typing_buf is not None:
            self._undo_stack.append(('type', self._typing_buf))
            self._typing_buf = None

    def type(self, s: str) -> None:
        self._text += s
        if self._typing_buf is None:
            self._typing_buf = s
        else:
            self._typing_buf += s
        self._redo_stack.clear()

    def erase(self, n: int) -> None:
        self._commit_typing()
        if self._text:
            removed = self._text[-n:]
            self._text = self._text[:max(0, len(self._text) - n)]
            self._undo_stack.append(('erase', removed))
            self._redo_stack.clear()

    def mark(self) -> None:
        self._commit_typing()

    def undo(self) -> bool:
        self._commit_typing()
        if not self._undo_stack:
            return False
        op, data = self._undo_stack.pop()
        if op == 'type':
            self._text = self._text[:len(self._text) - len(data)]
        else:
            self._text += data
        self._redo_stack.append((op, data))
        return True

    def redo(self) -> bool:
        self._commit_typing()
        if not self._redo_stack:
            return False
        op, data = self._redo_stack.pop()
        if op == 'type':
            self._text += data
        else:
            self._text = self._text[:len(self._text) - len(data)]
        self._undo_stack.append((op, data))
        return True

    def text(self) -> str:
        return self._text
