def run_rover(grid: list[str], commands: str) -> tuple[int, int, str]:
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find the start cell
    start_r, start_c = None, None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start_r, start_c = r, c
                break
        if start_r is not None:
            break

    # Build portal map: letter -> list of (row, col)
    portals: dict[str, list[tuple[int, int]]] = {}
    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if 'a' <= ch <= 'z':
                portals.setdefault(ch, []).append((r, c))

    r, c = start_r, start_c
    facing = 'N'

    dirs = {'N': (-1, 0), 'E': (0, 1), 'S': (1, 0), 'W': (0, -1)}
    left_turn = {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'}
    right_turn = {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}
    opposite_dir = {'N': 'S', 'S': 'N', 'E': 'W', 'W': 'E'}

    def one_step(d: str) -> None:
        nonlocal r, c
        dr, dc = dirs[d]
        nr, nc = r + dr, c + dc
        # Step 1: check bounds and wall
        if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
            return
        if grid[nr][nc] == '#':
            return
        # Step 2: move onto the cell
        r, c = nr, nc
        # Sliding
        while grid[r][c] == '~':
            nr2, nc2 = r + dr, c + dc
            if nr2 < 0 or nr2 >= rows or nc2 < 0 or nc2 >= cols:
                break
            if grid[nr2][nc2] == '#':
                break
            r, c = nr2, nc2
        # Portal check
        cell = grid[r][c]
        if 'a' <= cell <= 'z':
            for pr, pc in portals[cell]:
                if pr != r or pc != c:
                    r, c = pr, pc
                    break

    # Parse and execute commands
    i = 0
    n = len(commands)
    while i < n:
        ch = commands[i]
        if ch not in 'FBLR':
            raise ValueError(f"Invalid character '{ch}' at position {i}")
        i += 1
        # Parse optional repeat count
        if i < n and commands[i].isdigit():
            count_start = i
            while i < n and commands[i].isdigit():
                i += 1
            count_str = commands[count_start:i]
            if count_str == '0':
                raise ValueError("Count of 0 is not allowed")
            if len(count_str) > 1 and count_str[0] == '0':
                raise ValueError(f"Leading zero in count '{count_str}'")
            count = int(count_str)
            if count < 1:
                raise ValueError("Repeat count must be at least 1")
        else:
            count = 1
        # Execute the command `count` times
        for _ in range(count):
            if ch == 'L':
                facing = left_turn[facing]
            elif ch == 'R':
                facing = right_turn[facing]
            elif ch == 'F':
                one_step(facing)
            else:  # ch == 'B'
                one_step(opposite_dir[facing])

    return (r, c, facing)
