import re


def coin_total(amounts: list[str]) -> str:
    def parse(amount: str) -> int:
        s = amount
        if not s:
            raise ValueError("empty string")

        negative = False
        if s[0] == '-':
            negative = True
            s = s[1:]
            if not s or s[0] == ' ':
                raise ValueError("space or nothing after '-'")
        elif s[0] == '+':
            raise ValueError("plus sign")

        if '  ' in s or s[0] == ' ' or s[-1] == ' ':
            raise ValueError("bad spacing")

        parts = s.split(' ')
        if not parts:
            raise ValueError("empty amount")

        unit_order = {'g': 0, 's': 1, 'c': 2}
        prev_idx = -1

        for part in parts:
            if len(part) < 2:
                raise ValueError(f"term too short: {part!r}")
            if not all(ch.isdigit() for ch in part[:-1]):
                raise ValueError(f"non-digit characters in term: {part!r}")
            if part[-1] not in unit_order:
                raise ValueError(f"bad unit: {part!r}")

            idx = unit_order[part[-1]]
            if idx <= prev_idx:
                raise ValueError(f"wrong order or repeated unit")
            prev_idx = idx

        total_chips = 0
        for part in parts:
            num = int(part[:-1])
            unit = part[-1]
            if unit == 'g':
                total_chips += num * 493
            elif unit == 's':
                total_chips += num * 17
            else:
                total_chips += num

        return -total_chips if negative else total_chips

    total = 0
    for amt in amounts:
        total += parse(amt)

    if total == 0:
        return "0c"

    negative = total < 0
    total = abs(total)

    g = total // 493
    total %= 493
    s = total // 17
    c = total % 17

    pieces = []
    if g > 0:
        pieces.append(f"{g}g")
    if s > 0:
        pieces.append(f"{s}s")
    if c > 0:
        pieces.append(f"{c}c")

    result = " ".join(pieces)
    if negative:
        result = "-" + result
    return result
