def mask_account_numbers(text: str) -> str:
    n = len(text)
    if n == 0:
        return text

    # Find all digit positions
    digit_positions = [i for i, c in enumerate(text) if c.isdigit()]
    if not digit_positions:
        return text

    # Build runs: group consecutive digit positions that are linked
    # (adjacent or separated by exactly one space/hyphen)
    runs = []
    current_run = [digit_positions[0]]
    for k in range(1, len(digit_positions)):
        prev = digit_positions[k - 1]
        curr = digit_positions[k]
        gap = curr - prev - 1
        if gap == 0:
            current_run.append(curr)
        elif gap == 1:
            if text[prev + 1] in (' ', '-'):
                current_run.append(curr)
            else:
                runs.append(current_run)
                current_run = [curr]
        else:
            runs.append(current_run)
            current_run = [curr]
    runs.append(current_run)

    # Mask runs of 8 or more digits (keep last 4 digits, star the rest)
    result = list(text)
    for run in runs:
        if len(run) >= 8:
            last_four = set(run[-4:])
            for pos in run[:-4]:
                result[pos] = '*'

    return ''.join(result)
