from datetime import datetime, timedelta


def shift_working_days(start: str, n: int, holidays: list[str], rest_days: list[int]) -> str:
    if len(set(rest_days)) == 7:
        raise ValueError("rest_days contains all seven weekdays")

    holidays_set = set(holidays)
    start_date = datetime.strptime(start, "%Y-%m-%d")

    def is_working_day(d: datetime) -> bool:
        return d.weekday() not in rest_days and d.strftime("%Y-%m-%d") not in holidays_set

    if n > 0:
        count = 0
        d = start_date + timedelta(days=1)
        while count < n:
            if is_working_day(d):
                count += 1
            d += timedelta(days=1)
        return d.strftime("%Y-%m-%d")

    elif n < 0:
        count = 0
        d = start_date - timedelta(days=1)
        while count < abs(n):
            if is_working_day(d):
                count += 1
            d -= timedelta(days=1)
        return d.strftime("%Y-%m-%d")

    else:  # n == 0
        if is_working_day(start_date):
            return start_date.strftime("%Y-%m-%d")
        d = start_date + timedelta(days=1)
        while True:
            if is_working_day(d):
                return d.strftime("%Y-%m-%d")
            d += timedelta(days=1)
