def league_table(matches: list[tuple[str, int, str, int]]) -> list[tuple[int, str, int, int, int]]:
    pts: dict[str, int] = {}
    gf: dict[str, int] = {}
    ga: dict[str, int] = {}

    for home, hg, away, ag in matches:
        if home == away:
            raise ValueError("Same team on both sides of a match")

        pts.setdefault(home, 0)
        pts.setdefault(away, 0)
        gf.setdefault(home, 0)
        gf.setdefault(away, 0)
        ga.setdefault(home, 0)
        ga.setdefault(away, 0)

        gf[home] += hg
        ga[home] += ag
        gf[away] += ag
        ga[away] += hg

        if hg > ag:
            pts[home] += 3
        elif hg < ag:
            pts[away] += 3
        else:
            pts[home] += 1
            pts[away] += 1

    def triple(t: str):
        return (pts[t], gf[t] - ga[t], gf[t])

    teams = sorted(pts.keys(), key=lambda t: (-pts[t], -(gf[t] - ga[t]), -gf[t], t))

    result: list[tuple[int, str, int, int, int]] = []
    i = 0
    n = len(teams)
    while i < n:
        j = i
        while j < n and triple(teams[j]) == triple(teams[i]):
            j += 1
        rank = i + 1
        for k in range(i, j):
            result.append((rank, teams[k], pts[teams[k]], gf[teams[k]] - ga[teams[k]], gf[teams[k]]))
        i = j

    return result
