def runoff_winner(ballots: list[list[str]]) -> tuple[str, list[str]]:
    # Collect all candidates (any name appearing on at least one ballot)
    candidates: set[str] = set()
    for ballot in ballots:
        for c in ballot:
            candidates.add(c)

    if not candidates:
        raise ValueError("No candidates found")

    eliminated: list[str] = []
    current = set(candidates)
    round1_votes: dict[str, int] = {}
    round_num = 0

    while True:
        # Count votes this round
        votes: dict[str, int] = {c: 0 for c in current}
        non_exhausted = 0

        for ballot in ballots:
            for c in ballot:
                if c in current:
                    votes[c] += 1
                    non_exhausted += 1
                    break

        # Remember round‑1 votes for tie‑breaking
        if round_num == 0:
            round1_votes = dict(votes)

        # Check for a strict majority (> half of non‑exhausted ballots)
        threshold = non_exhausted / 2.0
        for c in current:
            if votes[c] > threshold:
                return (c, eliminated)

        # If only one candidate remains, they win
        if len(current) == 1:
            return (next(iter(current)), eliminated)

        # Eliminate one candidate
        min_votes = min(votes[c] for c in current)
        tied = [c for c in current if votes[c] == min_votes]

        # Tie‑break 1: fewest votes in round 1
        if len(tied) > 1:
            min_r1 = min(round1_votes[c] for c in tied)
            tied = [c for c in tied if round1_votes[c] == min_r1]

        # Tie‑break 2: name comes LAST alphabetically
        if len(tied) > 1:
            tied.sort()
            to_eliminate = tied[-1]
        else:
            to_eliminate = tied[0]

        eliminated.append(to_eliminate)
        current.discard(to_eliminate)
        round_num += 1
