def grow_moss(cells: str, steps: int) -> str:
    valid = set('.oO')
    for c in cells:
        if c not in valid:
            raise ValueError(f"Invalid character: {c!r}")

    if steps == 0 or not cells:
        return cells

    def one_step(s: str) -> str:
        n = len(s)
        out = []
        for i in range(n):
            left = s[i - 1] if i > 0 else '.'
            right = s[i + 1] if i < n - 1 else '.'
            live = (1 if left in ('o', 'O') else 0) + (1 if right in ('o', 'O') else 0)
            cur = s[i]
            if cur == '.':
                out.append('o' if live == 1 else '.')
            elif cur == 'o':
                if live == 2:
                    out.append('O')
                elif live == 0:
                    out.append('.')
                else:
                    out.append('o')
            else:  # 'O'
                if live == 2:
                    out.append('.')
                elif live == 0:
                    out.append('o')
                else:
                    out.append('O')
        return ''.join(out)

    visited = {}   # state -> step index at which it was first seen
    states = []    # states[k] = row after k steps

    current = cells
    visited[current] = 0
    states.append(current)

    for s in range(1, steps + 1):
        current = one_step(current)
        if current in visited:
            t0 = visited[current]          # first step in the cycle
            cycle_len = s - t0            # length of the cycle
            if s <= steps:                # steps falls inside or past the cycle
                idx = t0 + (steps - t0) % cycle_len
                return states[idx]
        visited[current] = s
        states.append(current)

    # No cycle detected within `steps` iterations (small `steps` or no repeat yet)
    return current
