def fill_template(template: str, values: dict) -> str:
    def parse_filter(piece: str):
        if ':' in piece:
            name, _, arg = piece.partition(':')
            if name in ('pad', 'cut'):
                if not arg or not arg.isdigit():
                    raise ValueError(f"Malformed filter '{piece}'")
                return (name, int(arg))
            raise ValueError(f"Filter '{name}' does not take an argument")
        if piece in ('upper', 'lower', 'rev'):
            return (piece, None)
        raise ValueError(f"Unknown filter '{piece}'")

    def apply_filter(f, value: str) -> str:
        name, arg = f
        if name == 'upper':
            return value.upper()
        if name == 'lower':
            return value.lower()
        if name == 'rev':
            return value[::-1]
        if name == 'pad':
            if len(value) < arg:
                return value + '.' * (arg - len(value))
            return value
        if name == 'cut':
            return value[:arg]
        raise ValueError(f"Unknown filter '{name}'")

    def process_field(content: str) -> str:
        pieces = content.split('|')
        name = pieces[0]
        if name == '':
            raise ValueError("Empty field name")
        filters = [parse_filter(p) for p in pieces[1:]]
        if name in values:
            value = str(values[name])
            for f in filters:
                value = apply_filter(f, value)
            return value
        return f"<{name}?>"

    result = []
    i = 0
    n = len(template)

    while i < n:
        ch = template[i]

        if ch == '{':
            if i + 1 < n and template[i + 1] == '{':
                result.append('{')
                i += 2
            else:
                j = i + 1
                while j < n and template[j] != '}':
                    j += 1
                if j >= n:
                    raise ValueError("Unclosed field: no closing }")
                content = template[i + 1:j]
                if '{' in content:
                    raise ValueError("Field content contains '{'")
                result.append(process_field(content))
                i = j + 1

        elif ch == '}':
            if i + 1 < n and template[i + 1] == '}':
                result.append('}')
                i += 2
            else:
                raise ValueError("Unmatched '}' in template")

        else:
            result.append(ch)
            i += 1

    return ''.join(result)
