class TickScheduler:
    def __init__(self):
        self._current_time = 0
        self._counter = 0
        self._tasks = {}  # name -> {'at': int, 'every': int|None, 'add_order': int}

    def add(self, name: str, at: int, every: int | None = None) -> None:
        if at < self._current_time:
            raise ValueError(f"at ({at}) is earlier than current time ({self._current_time})")
        if every is not None:
            if not isinstance(every, int) or every <= 0:
                raise ValueError("every must be a positive integer")
        self._tasks[name] = {
            "at": at,
            "every": every,
            "add_order": self._counter,
        }
        self._counter += 1

    def cancel(self, name: str) -> bool:
        if name in self._tasks:
            del self._tasks[name]
            return True
        return False

    def run_until(self, t: int) -> list[tuple[int, str]]:
        if t < self._current_time:
            raise ValueError(f"t ({t}) is earlier than current time ({self._current_time})")

        events: list[tuple[int, int, str]] = []  # (firing_time, add_order, name)

        for name, task in list(self._tasks.items()):
            at = task["at"]
            every = task["every"]
            add_order = task["add_order"]

            if at > t:
                continue  # won't fire within this window

            if every is None:
                events.append((at, add_order, name))
                del self._tasks[name]
            else:
                firings = []
                fire_at = at
                while fire_at <= t:
                    firings.append(fire_at)
                    fire_at += every
                for ft in firings:
                    events.append((ft, add_order, name))
                self._tasks[name]["at"] = at + len(firings) * every

        events.sort(key=lambda e: (e[0], e[1]))
        result = [(ft, name) for ft, _, name in events]
        self._current_time = t
        return result

    def pending(self) -> list[str]:
        return sorted(self._tasks.keys())
