def wrap_note(text: str, width: int) -> list[str]:
    if width < 2:
        raise ValueError("width must be at least 2")

    paragraphs = text.split("\n")
    result: list[str] = []

    for paragraph in paragraphs:
        words = [w for w in paragraph.split(" ") if w != ""]

        if not words:
            result.append("")
            continue

        lines: list[str] = []
        current: str = ""

        for word in words:
            if len(word) <= width:
                if current == "":
                    current = word
                elif len(current) + 1 + len(word) <= width:
                    current += " " + word
                else:
                    lines.append(current)
                    current = word
            else:
                if current != "":
                    lines.append(current)
                piece = word
                while len(piece) > width:
                    lines.append(piece[: width - 1] + "-")
                    piece = piece[width - 1:]
                current = piece

        if current != "":
            lines.append(current)

        result.extend(lines)

    return result
