def dock_title(name: str) -> str:
    words = name.split()
    if not words:
        return ""

    n_words = len(words)
    small_words = frozenset({"a", "an", "and", "of", "the", "in", "on", "to"})

    def transform(part: str, word_idx: int, part_idx: int, n_parts: int) -> str:
        # Rule a: contains at least one digit
        if any(c.isdigit() for c in part):
            return part.upper()

        # Rule b: 2 or 3 characters, all uppercase A-Z
        if len(part) in (2, 3) and part.isalpha() and part.isupper():
            return part

        # Rule c: small word, not first part of first word, not last part of last word
        is_first = word_idx == 0 and part_idx == 0
        is_last = word_idx == n_words - 1 and part_idx == n_parts - 1
        if part.lower() in small_words and not is_first and not is_last:
            return part.lower()

        # Rule d: first char upper, rest lower
        if not part:
            return ""
        return part[0].upper() + part[1:].lower()

    result_words = []
    for word_idx, word in enumerate(words):
        parts = word.split("-")
        n_parts = len(parts)
        transformed_parts = [
            transform(part, word_idx, part_idx, n_parts)
            for part_idx, part in enumerate(parts)
        ]
        result_words.append("-".join(transformed_parts))

    return " ".join(result_words)
