def curve_grades(scores: dict) -> dict:
    if not scores:
        return {}

    present = {name: s for name, s in scores.items() if s is not None}
    n = len(present)

    # Integer-arithmetic ceilings: ceil(n/5), ceil(n/2), ceil(4n/5)
    limit_a = (n + 4) // 5
    limit_b = (n + 1) // 2
    limit_c = (4 * n + 4) // 5

    result = {}
    for name, score in scores.items():
        if score is None:
            result[name] = "X"
        else:
            rank = 1 + sum(1 for s in present.values() if s > score)
            if rank <= limit_a:
                result[name] = "A"
            elif rank <= limit_b:
                result[name] = "B"
            elif rank <= limit_c:
                result[name] = "C"
            else:
                result[name] = "D"

    return result
